import java.io.InputStream;
import java.io.IOException;
import java.util.Arrays;
import java.util.PriorityQueue;

public class Main {

    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int buflen = 0;

        private boolean hasNextByte() {
            if (ptr < buflen) return true;
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            return buflen > 0;
        }

        private int readByte() {
            if (hasNextByte()) return buffer[ptr++];
            return -1;
        }

        public int nextInt() {
            int b = readByte();
            while (b <= ' ' && b != -1) {
                b = readByte();
            }
            if (b == -1) return -1;
            int res = 0;
            while (b >= '0' && b <= '9') {
                res = res * 10 + (b - '0');
                b = readByte();
            }
            return res;
        }
    }

    static class Item implements Comparable<Item> {
        int price;
        int type;
        int index;

        public Item(int price, int type, int index) {
            this.price = price;
            this.type = type;
            this.index = index;
        }

        @Override
        public int compareTo(Item other) {
            if (this.price != other.price) {
                return Integer.compare(this.price, other.price);
            }
            return Integer.compare(this.type, other.type);
        }
    }

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        int n = scanner.nextInt();
        int t = scanner.nextInt();

        int[] types = new int[n];
        for (int i = 0; i < n; i++) {
            types[i] = scanner.nextInt();
        }

        int[] prices = new int[n];
        for (int i = 0; i < n; i++) {
            prices[i] = scanner.nextInt();
        }

        // Contar quantos itens de cada tipo existem
        int[] count = new int[t + 1];
        for (int i = 0; i < n; i++) {
            count[types[i]]++;
        }

        // Alocar listas para cada tipo
        int[][] typePrices = new int[t + 1][];
        for (int i = 1; i <= t; i++) {
            typePrices[i] = new int[count[i]];
        }

        int[] fillPtr = new int[t + 1];
        for (int i = 0; i < n; i++) {
            int tp = types[i];
            typePrices[tp][fillPtr[tp]++] = prices[i];
        }

        // Ordenar os preços de cada tipo
        for (int i = 1; i <= t; i++) {
            if (count[i] > 0) {
                Arrays.sort(typePrices[i]);
            }
        }

        int[] currentIdx = new int[t + 1];
        PriorityQueue<Item> pq = new PriorityQueue<>();

        // Inserir o primeiro item de cada tipo presente
        for (int i = 1; i <= t; i++) {
            if (count[i] > 0) {
                pq.add(new Item(typePrices[i][0], i, 0));
            }
        }

        int c = scanner.nextInt();
        long totalRevenue = 0;

        for (int j = 0; j < c; j++) {
            int u = scanner.nextInt();
            if (u > 0) {
                // Cliente decidido
                if (currentIdx[u] < typePrices[u].length) {
                    int price = typePrices[u][currentIdx[u]];
                    totalRevenue += price;
                    currentIdx[u]++;
                    if (currentIdx[u] < typePrices[u].length) {
                        pq.add(new Item(typePrices[u][currentIdx[u]], u, currentIdx[u]));
                    }
                }
            } else {
                // Cliente indeciso
                while (!pq.isEmpty()) {
                    Item top = pq.peek();
                    if (top.index != currentIdx[top.type]) {
                        pq.poll(); // Item já vendido ou desatualizado
                    } else {
                        break;
                    }
                }

                if (!pq.isEmpty()) {
                    Item top = pq.poll();
                    int tp = top.type;
                    totalRevenue += top.price;
                    currentIdx[tp]++;
                    if (currentIdx[tp] < typePrices[tp].length) {
                        pq.add(new Item(typePrices[tp][currentIdx[tp]], tp, currentIdx[tp]));
                    }
                }
            }
        }

        System.out.println(totalRevenue);
    }
}
